from jsonb_to_recordset($json$[{"id":"che-so-176","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-ideal solution is one that","options":["deviates from Raoult’s law","obeys Raoult’s law at every mole fraction","has $\\Delta H_{\\mathrm{mix}}$ exactly zero","never boils"],"answer_index":0,"explanation":"Any measurable departure of vapour pressure from $p_i^\\circ x_i$ marks non-ideality.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-177","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Positive deviation from Raoult’s law means the observed vapour pressure is","options":["higher than the ideal value","lower than the ideal value","exactly zero","equal to $K_H$"],"answer_index":0,"explanation":"Weaker A–B forces let molecules escape more easily, so $p > p_{\\mathrm{ideal}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-178","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Negative deviation from Raoult’s law is accompanied by","options":["$\\Delta H_{\\mathrm{mix}} < 0$","$\\Delta H_{\\mathrm{mix}} > 0$","$\\Delta H_{\\mathrm{mix}} = 0$","$\\Delta V_{\\mathrm{mix}} > 0$ in every case"],"answer_index":0,"explanation":"Stronger A–B attractions release heat on mixing (exothermic).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-179","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a positively deviating pair, mixing typically causes the volume to","options":["increase ($\\Delta V_{\\mathrm{mix}} > 0$)","decrease","stay exactly additive","collapse to zero"],"answer_index":0,"explanation":"Weaker unlike attractions leave a slightly expanded, less tightly packed liquid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-180","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Chloroform and acetone show negative deviation because","options":["a hydrogen-bond-like attraction forms between the two molecules","the liquids repel strongly","they are immiscible","they ionise completely"],"answer_index":0,"explanation":"The chloroform hydrogen interacts with the acetone oxygen, strengthening A–B forces.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-181","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Ethanol–acetone is a common Intermediate example of","options":["positive deviation","negative deviation","an ideal mix","a solid solution"],"answer_index":0,"explanation":"Mixing breaks some ethanol hydrogen bonds, so A–B is weaker than A–A and the pair shows positive deviation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-182","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"n-Hexane and n-heptane are expected to behave as","options":["an ideal solution","a strongly positive pair","a strongly negative pair","an azeotrope only"],"answer_index":0,"explanation":"Adjacent homologues have nearly identical London forces, so the mix is essentially ideal.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-183","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"When A–B attractions are weaker than A–A and B–B, the mixture shows","options":["positive deviation and often a minimum-boiling azeotrope","negative deviation and a maximum-boiling azeotrope","strictly ideal behaviour","zero vapour pressure"],"answer_index":0,"explanation":"Weaker unlike forces raise vapour pressure; a maximum in p versus x gives a minimum-boiling azeotrope.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-184","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Nitric acid and water mix with heat released and a vapour-pressure curve below the Raoult line. The deviation is","options":["negative","positive","ideal","undefined"],"answer_index":0,"explanation":"Exothermic mixing plus $p < p_{\\mathrm{ideal}}$ is the signature of negative deviation.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-185","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Carbon disulphide and acetone form a pair with weaker unlike interactions, so one expects","options":["positive deviation","negative deviation","$\\Delta H_{\\mathrm{mix}} = 0$","i = 2"],"answer_index":0,"explanation":"CS2–acetone is a standard positively deviating pair.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-186","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For an ideal solution the plot of $p_A$ versus $x_A$ is","options":["linear from 0 to $p_A^\\circ$","concave upward","concave downward","a horizontal line"],"answer_index":0,"explanation":"Raoult’s law $p_A = p_A^\\circ x_A$ is a straight line through the origin and $(1, p_A^\\circ)$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-187","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A liquid pair with $\\Delta V_{\\mathrm{mix}}$ negative and $p$ below the ideal line is classified as","options":["non-ideal with negative deviation","ideal","positively deviating","colloidal"],"answer_index":0,"explanation":"Volume contraction and lowered vapour pressure both point to stronger A–B attractions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-188","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A binary liquid shows $\\Delta H_{\\mathrm{mix}}$ negative and total vapour pressure below the Raoult prediction at every composition. Distillation of this pair commonly yields","options":["a maximum-boiling azeotrope","a minimum-boiling azeotrope","an ideal vapour of unchanged composition","no condensate at any temperature"],"answer_index":0,"explanation":"Negative deviation produces a minimum in p versus x and therefore a maximum-boiling azeotrope.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"ideal-nonideal","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-189","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Colligative properties of a dilute solution depend on","options":["the number of solute particles, not their chemical identity","the colour of the solute","the charge of the solute only","the solvent density only"],"answer_index":0,"explanation":"Particle count (mole fraction or molality) fixes the size of a colligative effect for a given solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-190","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Relative lowering of vapour pressure is defined as","options":["$(p^\\circ - p) / p^\\circ$","$p^\\circ - p$","$p / p^\\circ$","$p^\\circ / p$"],"answer_index":0,"explanation":"It is the fractional drop in solvent vapour pressure caused by the solute.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-191","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For a dilute solution of a non-volatile non-electrolyte, $(p^\\circ - p) / p^\\circ$ equals","options":["the mole fraction of the solute","the molality","the molarity","the mass percent"],"answer_index":0,"explanation":"Raoult’s law gives $(p^\\circ - p)/p^\\circ = x_{\\mathrm{solute}}$ in the dilute non-volatile limit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-192","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The four classical colligative properties include relative lowering of vapour pressure, boiling-point elevation, freezing-point depression and","options":["osmotic pressure","viscosity","surface tension","refractive index"],"answer_index":0,"explanation":"Those four effects depend on the number of solute particles, not on their nature.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-193","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Relative lowering of vapour pressure does not depend on","options":["the chemical identity of a non-electrolyte solute","the mole fraction of that solute","the vapour pressure of the pure solvent","whether the solute is present at all"],"answer_index":0,"explanation":"Any non-volatile non-electrolyte at the same $x_B$ produces the same relative lowering.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-194","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A non-volatile solute reduces vapour pressure because","options":["the mole fraction of solvent molecules at the surface falls","the solute evaporates faster than the solvent","$K_H$ becomes infinite","the solution must freeze"],"answer_index":0,"explanation":"Fewer solvent molecules occupy the surface, so the escape rate into the vapour falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-195","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"In the dilute limit the vapour pressure of a solution of a non-volatile solute is $p^\\circ$ multiplied by","options":["the mole fraction of the solvent","the mole fraction of the solute","the molality","$1 - M$"],"answer_index":0,"explanation":"$p = p^\\circ x_{\\mathrm{solvent}}$ is Raoult’s law for the solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-196","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The molar mass of a non-volatile solute can be estimated from a measurement of","options":["relative lowering of vapour pressure","the colour of the solution","the density of the pure solute alone","$K_H$ of an unrelated gas"],"answer_index":0,"explanation":"$(p^\\circ - p)/p^\\circ = n_B / (n_A + n_B)$ can be solved for $M_B$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-197","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The Ostwald–Walker dynamic method is a classical experiment for measuring","options":["relative lowering of vapour pressure","osmotic pressure","Henry’s constant","pH"],"answer_index":0,"explanation":"Air is passed through solution and then through pure solvent; the mass losses give $(p^\\circ - p)/p^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-198","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two dilute solutions that share the same mole fraction of non-electrolyte solute in the same solvent show","options":["the same relative lowering","different relative lowerings proportional to solute mass only","zero lowering","lowering equal to $K_b$"],"answer_index":0,"explanation":"Relative lowering tracks $x_B$, which is identical for the two solutions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-199","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A solvent has $p^\\circ = 80$ torr. After a non-volatile solute is added the pressure is 76 torr. Relative lowering is","options":["0.050","4.0","76","0.95"],"answer_index":0,"explanation":"$(80 - 76)/80 = 0.050$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-200","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Relative lowering of 0.020 is recorded for a dilute non-electrolyte. The mole fraction of solute is","options":["0.020","0.980","2.0","0.20"],"answer_index":0,"explanation":"For a dilute non-volatile non-electrolyte, $(p^\\circ - p)/p^\\circ = x_B$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"relative-lowering","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
